section.pre:
chapter:first-child { color: navy; }
chapter:last-child { color: teal; }
chapter:only-child { color: gray; }
chapter:first-of-type { color: purple; }

chapter:nth-child(odd) { color: navy; }
chapter:nth-child(2n + 1) { color: teal; }
chapter:nth-child(2 of [status="active"]) { color: purple; }

:root { color: navy; }
chapter:empty { display: none; }
:scope > chapter { color: teal; }

chapter:not([status="draft"]) { color: navy; }
:is(chapter, appendix) > title { color: teal; }
:where([compact]) paragraph { font-size: 10pt; }
section:has(> figure) { color: purple; }
title:has(+ paragraph) { color: gray; }
